const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M16 3v4M8 3v4M3 11h18m-13 4h1m3 0h1m3 0h1m-9 3h1m3 0h1"/>',chart:'<path d="M4 20V10m8 10V4m8 16v-7"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2"/><circle cx="15" cy="12" r="2"/><circle cx="8" cy="18" r="2"/>',bell:'<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>',leaf:'<path d="M6 19C0 7 12 3 20 4c1 10-5 17-14 15Zm0 0 9-10"/>'};
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.leaf}</svg>`;
const plant=`<svg class="hero-art" viewBox="0 0 180 180" fill="none" aria-hidden="true"><ellipse cx="95" cy="163" rx="53" ry="7" fill="#d5dac4"/><path d="M92 103C89 75 92 48 111 30M92 87C78 68 61 57 49 56M94 64C105 56 119 54 129 53" stroke="#485c43" stroke-width="3" stroke-linecap="round"/><path d="M107 45C102 26 116 15 136 18c1 19-8 31-29 27Z" fill="#8b9f72" stroke="#485c43" stroke-width="1.8"/><path d="M79 76C54 84 34 67 36 47c23-6 40 7 43 29Z" fill="#afbc91" stroke="#485c43" stroke-width="1.8"/><path d="M104 63c0-22 21-29 36-17-2 22-19 28-36 17Z" fill="#b8c19b" stroke="#485c43" stroke-width="1.8"/><path d="M58 101h69l-8 48c-2 14-50 14-53 0Z" fill="#fffdf1" stroke="#485c43" stroke-width="2"/><path d="M55 100c0-4 3-6 7-6h62c4 0 7 2 7 6s-3 7-7 7H62c-4 0-7-3-7-7Z" fill="#f4f0db" stroke="#485c43" stroke-width="2"/><circle cx="82" cy="124" r="2.5" fill="#485c43"/><circle cx="105" cy="124" r="2.5" fill="#485c43"/><path d="M88 134q6 7 12 0" stroke="#485c43" stroke-width="2" stroke-linecap="round"/><ellipse cx="74" cy="132" rx="5" ry="3" fill="#e9b9a8"/><ellipse cx="113" cy="132" rx="5" ry="3" fill="#e9b9a8"/><path d="m151 88 3-8 3 8 8 3-8 3-3 8-3-8-8-3Z" fill="#d1a479"/><path d="m25 114 2-5 2 5 5 2-5 2-2 5-2-5-5-2Z" fill="#a2ad87"/></svg>`;
const navs=[['today','home','Hoy'],['calendar','calendar','Calendario'],['progress','chart','Progreso'],['goals','target','Metas'],['settings','settings','Ajustes']];
let view='today',filter='all',selectedDay=6,month=10,year=2026,period='Mes',dark=false,reminders=true,accent='mint';
let habits=[{id:1,name:'Entrenar',emoji:'🏋️',category:'Movimiento',color:'peach',type:'check',target:1,value:0},{id:2,name:'Estudiar portugués',emoji:'💬',category:'Aprendizaje',color:'lavender',type:'time',target:30,value:15},{id:3,name:'Beber agua',emoji:'💧',category:'Bienestar',color:'blue',type:'count',target:8,value:4},{id:4,name:'Leer un poquito',emoji:'📖',category:'Para mí',color:'yellow',type:'time',target:20,value:20},{id:5,name:'Estudiar informática',emoji:'💻',category:'Aprendizaje',color:'mint',type:'time',target:45,value:45},{id:6,name:'Regar las plantas',emoji:'🪴',category:'Mi espacio',color:'pink',type:'check',target:1,value:1},{id:7,name:'Practicar Valorant',emoji:'🎯',category:'Tiempo libre',color:'lavender',type:'time',target:30,value:0},{id:8,name:'Practicar OPTCG',emoji:'🃏',category:'Tiempo libre',color:'peach',type:'check',target:1,value:0}];
const dayValues={6:{}};habits.forEach(h=>dayValues[6][h.id]=h.value);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const done=()=>habits.filter(h=>h.value>=h.target).length;
const percent=()=>Math.round(done()/habits.length*100);
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('visible'),2800)}
function habitCard(h){const completed=h.value>=h.target;return `<article class="habit" style="background:var(--${h.color})"><div class="habit-top"><div><span class="habit-icon">${h.emoji}</span><span class="category">${esc(h.category)}</span></div><button class="habit-toggle ${completed?'done':''}" data-toggle="${h.id}" aria-label="${completed?'Desmarcar':'Completar'} ${esc(h.name)}" aria-pressed="${completed}">${completed?'✓':''}</button></div><h3>${esc(h.name)}</h3><div class="detail">${h.type==='check'?(completed?'Hecho. ¡Bien por ti!':'Un pequeño paso para hoy'):h.type==='time'?`${h.target} minutos para ti`:`Tu meta: ${h.target} vasos al día`}</div>${h.type!=='check'?`<div class="habit-bottom"><div class="progress-track"><div class="progress-fill" style="width:${Math.min(100,h.value/h.target*100)}%"></div></div><div class="stepper"><button data-step="${h.id}" data-delta="-1" aria-label="Restar ${h.type==='time'?'5 minutos':'1 vaso'} a ${esc(h.name)}">−</button><span>${h.value}/${h.target}${h.type==='time'?' min':''}</span><button data-step="${h.id}" data-delta="1" aria-label="Sumar ${h.type==='time'?'5 minutos':'1 vaso'} a ${esc(h.name)}">+</button></div></div>`:''}</article>`}
function rail(){return `<aside class="rail"><section class="panel center"><div class="panel-label"><h3>Tu día, en un vistazo</h3><span>☀</span></div><div class="ring-wrap"><svg class="ring" viewBox="0 0 146 146"><circle cx="73" cy="73" r="61" stroke="var(--line)"/><circle cx="73" cy="73" r="61" stroke="#a5b58a" stroke-dasharray="${percent()*3.833} 383.3" stroke-linecap="round"/></svg><div class="ring-value"><strong>${percent()}<span style="font-size:19px">%</span></strong><span>${done()} de ${habits.length} hábitos</span></div></div><p class="daily-caption">${done()===habits.length?'¡Lo hiciste! Celebra tu día.':'Cada pequeño paso cuenta.'}</p><div class="mini-stats"><div><strong>5 <span>🔥</span></strong><span>días de constancia</span></div><div><strong>21</strong><span>mejor racha</span></div></div></section><section class="panel"><div class="panel-label"><h3>Semillitas de la semana</h3><span>🌱</span></div>${[['Mover el cuerpo','3 / 4 días',75,'mint'],['Un ratito de lectura','80 / 100 min',80,'lavender']].map(([a,b,p,c])=>`<div class="goal-mini"><div class="row"><span>${a}</span><b>${b}</b></div><div class="progress-track"><div class="progress-fill" style="width:${p}%;background:var(--${c})"></div></div></div>`).join('')}<button class="text-link" data-nav="goals" style="margin-top:23px">Ver mis metas <span style="margin-left:10px">↗</span></button></section><div class="rail-quote">“No necesitas hacerlo perfecto.<br>Solo necesitas volver a intentarlo.”<div style="font-size:19px;margin-top:10px">〰</div></div></aside>`}
function today(){const filtered=habits.filter(h=>filter==='all'||(filter==='pending'?h.value<h.target:h.value>=h.target));return `<div class="workspace"><section><div class="hero"><div><div class="eyebrow">POQUITO A POQUITO, TODOS LOS DÍAS</div><h2>Las cosas bonitas<br>toman constancia.</h2><p>Hoy es un buen día para crecer a tu ritmo.</p></div>${plant}</div><div class="week" aria-label="Seleccionar día de la semana">${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map((d,i)=>`<button class="day ${selectedDay===i+2?'selected':''}" data-day="${i+2}" aria-label="${d} ${i+2} de noviembre" aria-pressed="${selectedDay===i+2}"><span>${d}</span><strong>${i+2}</strong><span class="day-dot"></span></button>`).join('')}</div><div class="section-title"><h2>${selectedDay===6?'Mis hábitos de hoy':`Mis hábitos · ${selectedDay} nov`}</h2><small>${habits.length} pequeñas oportunidades</small></div><div class="filters">${[['all','Todos'],['pending','Por hacer'],['done','Completados']].map(([id,label])=>`<button class="chip ${filter===id?'active':''}" data-filter="${id}">${label}${id==='done'?` · ${done()}`:''}</button>`).join('')}</div><div class="habit-list">${filtered.length?filtered.map(habitCard).join(''):'<div class="empty-state">Todo tranquilo por aquí. 🌿<br>Prueba con otro filtro.</div>'}</div></section>${rail()}</div>`}
const months=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
function calendar(){const offset=(new Date(year,month,1).getDay()+6)%7;const days=new Date(year,month+1,0).getDate();return `<div class="workspace"><section class="panel"><div class="cal-head"><h2>${months[month]} ${year}</h2><div><button class="chip" data-month="-1" aria-label="Mes anterior">←</button> <button class="chip" data-month="1" aria-label="Mes siguiente">→</button></div></div><div class="cal-grid">${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(d=>`<span class="cal-weekday">${d}</span>`).join('')}${'<span class="cal-cell empty"></span>'.repeat(offset)}${Array.from({length:days},(_,i)=>{const d=i+1,future=year>2026||(year===2026&&(month>10||(month===10&&d>6)));return `<button class="cal-cell ${selectedDay===d?'selected':''} ${future?'future':''}" data-calday="${d}" aria-label="Ver ${d} de ${months[month]}"><span>${d}</span><span class="dots">${future?'':Array.from({length:2+(d*3)%5},(_,k)=>`<i style="background:${['#a6b78b','#b8abdc','#e3b59e','#9cbbce'][k%4]}"></i>`).join('')}</span></button>`}).join('')}</div><div class="legend"><span><i style="background:#a6b78b"></i>Hábitos registrados</span><span>Un punto, un pequeño logro</span></div></section><aside class="rail"><section class="panel"><span class="eyebrow">TU HISTORIA, DÍA A DÍA</span><h2 style="margin:12px 0 8px">${selectedDay} de ${months[month].toLowerCase()}</h2><p class="muted" style="font-size:12px">${month===10&&year===2026&&selectedDay===6?'Estos son tus avances de hoy.':'Registros de ejemplo para explorar el calendario.'}</p>${(month===10&&year===2026&&selectedDay===6?habits.filter(h=>h.value>0):habits.filter((h,i)=>(i+selectedDay)%3!==0)).map(h=>`<div style="display:flex;gap:10px;align-items:center;margin-top:20px;font-size:12px"><span>${h.emoji}</span><span>${esc(h.name)}</span><span style="margin-left:auto;color:var(--muted)">✓</span></div>`).join('')}<p style="font-size:10px;color:var(--muted);margin-top:25px">El historial es ilustrativo en este prototipo.</p></section><div class="rail-quote">Cada punto es una vez<br>que elegiste cuidarte. ✨</div></aside></div>`}
function progress(){const data=period==='Mes'?[45,75,60,90,65,85]:period==='3 meses'?[42,58,53,69,74,85]:[25,38,47,52,68,85];const labels=period==='Mes'?['1 nov','2 nov','3 nov','4 nov','5 nov','6 nov']:period==='3 meses'?['Ago','Sep','Sep','Oct','Oct','Nov']:['Jun','Jul','Ago','Sep','Oct','Nov'];return `<div class="filters" style="margin-bottom:23px">${['Mes','3 meses','Año'].map(p=>`<button class="chip ${period===p?'active':''}" data-period="${p}">${p}</button>`).join('')}<span class="muted" style="margin-left:auto;font-size:11px;align-self:center">${period==='Mes'?'Noviembre 2026':period==='3 meses'?'Septiembre – noviembre 2026':'2026'} · Datos de ejemplo</span></div><div class="stats-grid"><div class="stat-card"><span>Hábitos completados</span><strong>${period==='Mes'?'32':period==='3 meses'?'286':'1.042'}</strong><small>↗ Cada vez más constante</small></div><div class="stat-card"><span>Constancia</span><strong>${period==='Mes'?'76':period==='3 meses'?'72':'68'}%</strong><small>Tu esfuerzo está floreciendo</small></div><div class="stat-card"><span>Mejor racha</span><strong>21 <span>días</span></strong><small>Un día a la vez 🔥</small></div></div><div class="workspace"><section><div class="panel" style="padding-bottom:48px"><div class="panel-label"><h3>Así vas creciendo</h3><span class="muted" style="font-size:10px">% de hábitos completados</span></div><div class="chart">${data.map((p,i)=>`<div class="bar-col"><small class="muted" style="font-size:10px">${p}%</small><i style="height:${p*1.3}px"></i><span>${labels[i]}</span></div>`).join('')}</div></div><div class="panel" style="margin-top:20px"><div class="panel-label"><h3>Tu jardín de constancia</h3><span class="muted" style="font-size:10px">${period==='Mes'?'Este mes':period==='3 meses'?'Últimos 3 meses':'Este año'}</span></div><div class="heatmap" style="grid-template-columns:repeat(${period==='Mes'?5:period==='3 meses'?13:26},1fr)">${Array.from({length:period==='Mes'?35:period==='3 meses'?91:182},(_,i)=>`<i class="l${(i*7+Math.floor(i/3))%4}" title="Actividad ilustrativa: nivel ${(i*7+Math.floor(i/3))%4}"></i>`).join('')}</div><div class="legend" style="justify-content:end">Menos <i style="background:#edf0e6"></i><i style="background:#dce5c9"></i><i style="background:#b8ce9f"></i><i style="background:#718d65"></i> Más</div></div></section>${rail()}</div>`}
function goals(){return `<div class="workspace"><div class="goal-cards">${[['🏋️','Mover el cuerpo','Entrenar 4 días por semana',3,4,'días','mint','¡Solo te falta una sesión!'],['📖','Hacer espacio para leer','Leer 100 minutos por semana',80,100,'min','lavender','20 minutos más y lo logras.'],['💬','Un poquito de português','Estudiar 600 minutos este mes',120,600,'min','peach','A tu ritmo: cada práctica suma.'],['💧','Cuidar mi hidratación','Cumplir mi objetivo de agua 20 días al mes',5,20,'días','blue','Ya sembraste tus primeros 5 días.']].map(([emoji,name,desc,n,total,unit,color,note])=>`<article class="goal-card"><div class="row"><h3>${emoji} &nbsp;${name}</h3><span class="badge" style="background:var(--${color})">${Math.round(n/total*100)}%</span></div><p>${desc}</p><div class="progress-track"><div class="progress-fill" style="width:${n/total*100}%;background:${color==='mint'?'#a5b58a':color==='lavender'?'#b7a8d8':color==='peach'?'#d8b594':'#96b7ce'}"></div></div><div class="row"><small class="muted">${n} de ${total} ${unit}</small><small class="muted">${total-n} ${unit} por avanzar</small></div><p style="margin-top:18px;font-size:11px">✦ ${note}</p></article>`).join('')}</div><aside class="rail"><section class="panel center">${plant}<h2>Crecer lleva tiempo.</h2><p class="muted" style="font-size:12px;margin-top:12px">Las metas te dan una dirección.<br>Tus pequeños hábitos te llevan allí.</p></section><section class="panel"><h3>Un recordatorio amable</h3><p class="muted" style="font-size:12px;margin:12px 0 18px">Te avisaremos cuando tu meta necesite un poquito de atención.</p><button class="text-link" data-nav="settings">Ajustar mis recordatorios ↗</button></section></aside></div>`}
function settings(){return `<div class="settings-layout"><section class="panel"><h3>Hazlo tuyo</h3><div class="setting-row"><div><strong>Modo oscuro</strong><p>Un descanso para tus ojos.</p></div><button class="switch ${dark?'on':''}" role="switch" aria-checked="${dark}" aria-label="Modo oscuro" id="dark-switch"></button></div><div class="setting-row"><div style="width:100%"><strong>Color de acento</strong><p>Elige el tono que te acompañe.</p><div class="swatches">${['mint','lavender','peach','blue','pink'].map(c=>`<button class="swatch ${accent===c?'selected':''}" data-accent="${c}" aria-label="Color ${c}" aria-pressed="${accent===c}" style="background:var(--${c})"></button>`).join('')}</div></div></div><div class="setting-row"><div><strong>Idioma</strong><p>Un espacio que habla como tú.</p></div><span class="muted">Español</span></div></section><section class="panel"><h3>Recordatorios amables</h3><div class="setting-row"><div><strong>Un empujoncito al día</strong><p>Vista previa de notificaciones.</p></div><button class="switch ${reminders?'on':''}" role="switch" aria-checked="${reminders}" aria-label="Recordatorios" id="reminder-switch"></button></div><div class="setting-row"><div><strong>Para empezar el día</strong><p>Hoy también puedes dar un pequeño paso.</p></div><input style="width:105px" aria-label="Horario de mañana" type="time" value="09:00" ${reminders?'':'disabled'}></div><div class="setting-row"><div><strong>Antes de descansar</strong><p>¿Cómo te fue hoy?</p></div><input style="width:105px" aria-label="Horario de noche" type="time" value="21:00" ${reminders?'':'disabled'}></div><button class="text-link" id="preview-notification" style="margin-top:17px" ${reminders?'':'disabled'}>Probar un recordatorio ↗</button></section><section class="panel"><h3>Tu información, contigo</h3><p class="muted" style="font-size:12px;margin:14px 0">Estás explorando un prototipo. Los cambios viven solo en esta pestaña y se reinician al recargar.</p><p class="muted" style="font-size:12px">La importación, exportación y las notificaciones reales estarán disponibles en la aplicación.</p><button class="chip" id="reset-demo" style="margin-top:20px">Restablecer demo</button></section><div class="panel center" style="background:var(--yellow);border:0"><span style="font-size:28px">🌱</span><h2 style="margin-top:12px">Poquito</h2><p style="font-size:12px;margin-top:10px">Tus hábitos, a tu ritmo.<br>Hecho para celebrar lo que sí logras.</p><span class="eyebrow" style="display:block;margin-top:20px">PROTOTIPO · VERSIÓN 0.1</span></div></div>`}
function render(){const current=navs.find(n=>n[0]===view);const titles={today:['Hola, Austin ☀','Un pequeño paso hoy. Un gran cambio con el tiempo.'],calendar:['Tus días cuentan.','Un calendario lleno de pequeños logros.'],progress:['Mira cuánto has crecido.','A veces, mirar atrás es la mejor forma de seguir.'],goals:['De poquito en poquito.','Dale una dirección a tus pequeños pasos.'],settings:['A tu manera.','Un espacio que se siente como tú.']};document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#today"><span class="brand-mark">${icon('leaf',23)}</span>poquito<span style="color:#8f9c73">.</span></a><p class="tagline">Tus hábitos, a tu ritmo.</p><nav class="nav" aria-label="Navegación principal">${navs.map(([id,ico,name])=>`<button data-nav="${id}" class="${id===view?'active':''}" ${id===view?'aria-current="page"':''}>${icon(ico)}${name}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note"><span style="font-size:23px">🌱</span><p>No tienes que hacerlo todo.<br><b>Solo un poquito cada día.</b></p></div><div class="profile"><span class="avatar">☺</span><div><strong>Austin</strong><small>Mi pequeño espacio</small></div><button style="margin-left:auto" data-nav="settings" aria-label="Abrir perfil">⌄</button></div></div></aside><main><header class="topbar"><span class="breadcrumb">Mi espacio <span style="margin:0 12px;color:#b1b6ac">/</span> <b>${current[2]}</b></span><a class="brand mobile-brand" href="#today"><span class="brand-mark">${icon('leaf',21)}</span>poquito.</a><div class="top-actions"><span class="demo">✧ Modo exploración</span><span class="muted desktop-date" style="font-size:11px">Vie, 6 nov 2026</span><button class="icon-button" data-nav="settings" aria-label="Ver recordatorios">${icon('bell',17)}</button></div></header><div class="heading"><div><h1>${titles[view][0]}</h1><p>${titles[view][1]}</p></div>${view==='today'?'<button class="primary" id="add-habit">Nuevo hábito <span>＋</span></button>':''}</div>${({today,calendar,progress,goals,settings})[view]()}<footer class="footer"><span>No es una carrera. Es tu camino.</span><span>Hecho de pequeños pasos 🌿</span></footer></main><nav class="mobile-nav" aria-label="Navegación móvil">${navs.map(([id,ico,name])=>`<button data-nav="${id}" class="${id===view?'active':''}" ${id===view?'aria-current="page"':''}>${icon(ico,19)}${name}</button>`).join('')}</nav></div>`;document.body.classList.toggle('dark',dark);if(accent!=='mint')document.documentElement.style.setProperty('--green',dark?'#c6b8df':({lavender:'#665783',peach:'#82614b',blue:'#48677e',pink:'#82596b'})[accent]);else document.documentElement.style.removeProperty('--green');bind()}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{location.hash=b.dataset.nav});document.querySelector('#add-habit')?.addEventListener('click',()=>document.querySelector('#habit-dialog').showModal());document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{const h=habits.find(h=>h.id===+b.dataset.toggle);h.value=h.value>=h.target?0:h.target;dayValues[selectedDay]={...dayValues[selectedDay],[h.id]:h.value};render();if(h.value>=h.target)toast('Un pequeño logro más. ¡Bien por ti! ✨')});document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{const h=habits.find(h=>h.id===+b.dataset.step);h.value=Math.max(0,h.value+(+b.dataset.delta)*(h.type==='time'?5:1));dayValues[selectedDay]={...dayValues[selectedDay],[h.id]:h.value};render()});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{dayValues[selectedDay]=Object.fromEntries(habits.map(h=>[h.id,h.value]));selectedDay=+b.dataset.day;habits.forEach((h,i)=>h.value=dayValues[selectedDay]?.[h.id]??(selectedDay<6&&i%3===selectedDay%3?h.target:0));render()});document.querySelectorAll('[data-month]').forEach(b=>b.onclick=()=>{month+=+b.dataset.month;if(month<0){month=11;year--}if(month>11){month=0;year++}selectedDay=1;render()});document.querySelectorAll('[data-calday]').forEach(b=>b.onclick=()=>{selectedDay=+b.dataset.calday;render()});document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{period=b.dataset.period;render()});document.querySelector('#dark-switch')?.addEventListener('click',()=>{dark=!dark;render()});document.querySelector('#reminder-switch')?.addEventListener('click',()=>{reminders=!reminders;render()});document.querySelectorAll('[data-accent]').forEach(b=>b.onclick=()=>{accent=b.dataset.accent;render()});document.querySelector('#preview-notification')?.addEventListener('click',()=>toast('🌱 Un poquito para ti: ¿qué hábito te gustaría cuidar hoy?'));document.querySelector('#reset-demo')?.addEventListener('click',()=>location.reload())}
document.querySelector('#close-dialog').onclick=()=>document.querySelector('#habit-dialog').close();document.querySelector('#habit-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});document.querySelector('#habit-form').onsubmit=e=>{e.preventDefault();const data=new FormData(e.target);const name=data.get('name').trim();if(!name){toast('Dale un nombre a tu nuevo hábito.');return}habits.push({id:Date.now(),name,emoji:'🌱',category:'Mi nuevo hábito',type:data.get('type'),target:data.get('type')==='check'?1:+data.get('target'),color:data.get('color'),value:0});document.querySelector('#habit-dialog').close();e.target.reset();filter='all';render();toast('Una nueva semillita en tu día. 🌱')};function route(){view=navs.some(n=>n[0]===location.hash.slice(1))?location.hash.slice(1):'today';render();window.scrollTo({top:0})}window.addEventListener('hashchange',route);route();
